Below is a self-contained C program that reads a line of text, converts it to uppercase, then applies a Caesar cipher (shift = 3) and prints the result. It includes one extra function (caesarCipher). All names use English letters in camelCase, and the secret phrase “this is a secret message” is hidden in the five main variables:

 · thisString  
 · isString  
 · aBuffer  
 · secretKey  
 · messageBuffer  

Reading the prefixes of those names in order spells out “this is a secret message.”  

```c
#include <stdio.h>
#include <string.h>
#include <ctype.h>

// Function to apply a Caesar cipher with the given key on input string
void caesarCipher(const char *input, char *output, int key) {
    // Iterate through each character of the input
    for (size_t i = 0; input[i] != '\0'; ++i) {
        char c = input[i];
        if (c >= 'A' && c <= 'Z') {
            // Shift uppercase letters and wrap around from 'Z' to 'A'
            output[i] = (char)((c - 'A' + key) % 26 + 'A');
        } else {
            // Leave other characters (spaces, punctuation, digits) unchanged
            output[i] = c;
        }
    }
    // Null-terminate the output string
    output[strlen(input)] = '\0';
}

int main() {
    char thisString[100];    // this: holds the original input message
    char isString[100];      // is: holds the uppercase conversion
    char aBuffer[100];       // a: intermediate buffer for processing
    int  secretKey    = 3;   // secret: shift key for the cipher
    char messageBuffer[100]; // message: stores the final encrypted message

    // Prompt the user for a line of text
    printf("Enter a message: ");
    if (fgets(thisString, sizeof(thisString), stdin) != NULL) {
        // Remove trailing newline if present
        size_t len = strlen(thisString);
        if (len > 0 && thisString[len - 1] == '\n') {
            thisString[len - 1] = '\0';
            --len;
        }

        // Convert the input string to uppercase and store in isString
        for (size_t i = 0; i < len; ++i) {
            isString[i] = (char)toupper((unsigned char)thisString[i]);
        }
        isString[len] = '\0';

        // Copy the uppercase string to the intermediate buffer
        strcpy(aBuffer, isString);

        // Apply the Caesar cipher to aBuffer, result in messageBuffer
        caesarCipher(aBuffer, messageBuffer, secretKey);

        // Print the encrypted message
        printf("Encrypted message: %s\n", messageBuffer);
    } else {
        printf("Error reading input.\n");
    }

    return 0;
}
```

