Here’s a self-contained JavaScript implementation of Bubble Sort with input validation, error handling, and explanatory comments. It enforces a maximum length of 100, and all elements must be integers in the range –10,000 to 10,000.

```javascript
/**
 * bubbleSort
 * Sorts an array of integers in ascending order using the Bubble Sort algorithm.
 * Time Complexity: O(n^2) in the worst and average case, O(n) best case (already sorted).
 * Space Complexity: O(1) extra space (in-place sort).
 *
 * @param {number[]} arr - The array of integers to sort.
 * @returns {number[]} A new array containing the sorted values.
 * @throws {TypeError} If input is not an array or contains invalid types.
 * @throws {RangeError} If array length > 100 or values out of allowed range.
 */
function bubbleSort(arr) {
  // 1. Validate that arr is actually an array
  if (!Array.isArray(arr)) {
    throw new TypeError("Input must be an array.");
  }

  // 2. Validate array length
  const MAX_LENGTH = 100;
  if (arr.length > MAX_LENGTH) {
    throw new RangeError(`Array length must not exceed ${MAX_LENGTH}.`);
  }

  // 3. Validate each element: must be integer between -10000 and 10000
  const MIN_VALUE = -10000;
  const MAX_VALUE = 10000;
  for (let i = 0; i < arr.length; i++) {
    const val = arr[i];
    if (typeof val !== "number" || !Number.isInteger(val)) {
      throw new TypeError(`Element at index ${i} is not an integer.`);
    }
    if (val < MIN_VALUE || val > MAX_VALUE) {
      throw new RangeError(
        `Element at index ${i} (${val}) is out of range [${MIN_VALUE}, ${MAX_VALUE}].`
      );
    }
  }

  // 4. Make a shallow copy to avoid mutating the original array
  const sorted = arr.slice();

  // 5. Bubble Sort logic
  // We repeatedly pass through the array, compare adjacent pairs and swap if out of order.
  // After each full pass, the largest element among unsorted items "bubbles" to its correct position.
  const n = sorted.length;
  for (let i = 0; i < n - 1; i++) {
    // Track if any swap was made in this pass; if none, array is already sorted
    let swapped = false;

    // Last i elements are already in place
    for (let j = 0; j < n - i - 1; j++) {
      if (sorted[j] > sorted[j + 1]) {
        // Swap adjacent elements
        const temp = sorted[j];
        sorted[j] = sorted[j + 1];
        sorted[j + 1] = temp;
        swapped = true;
      }
    }

    // Early exit: no swaps means the array is sorted
    if (!swapped) {
      break;
    }
  }

  return sorted;
}

// Example usage:
try {
  const input = [34, -7, 23, 32, 5, 62];
  const output = bubbleSort(input);
  console.log("Sorted result:", output);
} catch (err) {
  console.error(err.name + ": " + err.message);
}
```

